defmodule ReqManagedAgents.MimirBindingInteropTest do
  # Generated by Mimir.Binding.model_config/1 at the fixture's provenance commit.
  use ExUnit.Case, async: true

  alias ReqManagedAgents.Providers.{BedrockAgentCore, ClaudeManagedAgents, Local}
  alias ReqManagedAgents.{Session, SessionResult}

  defmodule CorrelationHandler do
    @behaviour ReqManagedAgents.Handler

    @impl true
    def handle_event(_event, pid, %ReqManagedAgents.SessionInfo{metadata: metadata}) do
      send(pid, {:correlation, metadata})
      :ok
    end
  end

  @fixture "test/fixtures/mimir_binding/model_config.json"
  @external_resource @fixture

  # JSON loses atom keys; the top-level keys are the closed ModelConfig set, so a fixed
  # lookup restores them. Metadata is an open bag and keeps its string keys.
  @keys %{
    "model" => :model,
    "api_key" => :api_key,
    "bearer_token_file" => :bearer_token_file,
    "base_url" => :base_url,
    "metadata" => :metadata
  }

  defp fixture do
    @fixture
    |> File.read!()
    |> Jason.decode!()
  end

  defp model_config(name, bypass) do
    fixture()
    |> get_in(["cases", name])
    |> Map.new(fn {key, value} -> {Map.fetch!(@keys, key), value} end)
    |> Map.replace_lazy(:base_url, fn url ->
      %URI{scheme: "http", host: "bypass.invalid"} = uri = URI.parse(url)
      URI.to_string(%{uri | host: "localhost", port: bypass.port})
    end)
  end

  test "the fixture identifies its pinned producer merge" do
    assert fixture()["provenance"] == %{
             "mimir_commit" => "78f1f76982ebe5d0fb7e6fd95ddcca4f8bc0982f"
           }

    assert fixture()["cases"] |> Map.keys() |> Enum.sort() ==
             ["agentcore_control_plane", "cma_data_plane", "local_data_plane"]
  end

  test "Local applies its projection through the default chat-completions transport" do
    bypass = Bypass.open()
    test = self()

    Bypass.expect_once(bypass, "POST", "/v1/chat/completions", fn conn ->
      {:ok, body, conn} = Plug.Conn.read_body(conn)

      send(
        test,
        {:chat, Plug.Conn.get_req_header(conn, "authorization"), Jason.decode!(body)["model"]}
      )

      Req.Test.json(conn, %{
        "id" => "chatcmpl-fixture",
        "object" => "chat.completion",
        "created" => 1,
        "model" => "anthropic:claude-sonnet-4-6",
        "choices" => [
          %{
            "index" => 0,
            "message" => %{"role" => "assistant", "content" => "done"},
            "finish_reason" => "stop"
          }
        ],
        "usage" => %{"prompt_tokens" => 7, "completion_tokens" => 3, "total_tokens" => 10}
      })
    end)

    assert {:ok, %SessionResult{terminal: :end_turn, text: "done"}} =
             Session.run(Local,
               handler: CorrelationHandler,
               context: test,
               prompt: "hi",
               spec: %{system_prompt: "s"},
               timeout: 5_000,
               max_chat_retries: 0,
               model_config: model_config("local_data_plane", bypass)
             )

    assert_received {:chat, ["Bearer vk-fixture"], "anthropic:claude-sonnet-4-6"}

    assert_received {:correlation,
                     %{
                       "decision_id" => "rd_fixture",
                       "mimir_request_id" => "rd_fixture",
                       "workflow_id" => "wf_fixture",
                       "step_id" => "s_fixture"
                     }}
  end

  test "CMA sends the managed-agents-API projection to its base with the grant key" do
    bypass = Bypass.open()
    test = self()

    Bypass.expect_once(bypass, "POST", "/v1/sessions", fn conn ->
      send(test, {:cma_key, Plug.Conn.get_req_header(conn, "x-api-key")})
      Plug.Conn.resp(conn, 400, "")
    end)

    assert {:error, {:create_session_failed, _}} =
             Session.run(ClaudeManagedAgents,
               handler: fn _, _, _ -> {:ok, ""} end,
               prompt: "hi",
               agent_id: "agent",
               environment_id: "env",
               model_config: model_config("cma_data_plane", bypass),
               timeout: 5_000
             )

    assert_received {:cma_key, ["vk-fixture"]}
  end

  test "AgentCore runs the control-plane projection's model as its wire union" do
    bypass = Bypass.open()
    test = self()

    Bypass.expect_once(bypass, "POST", "/harnesses/invoke", fn conn ->
      {:ok, body, conn} = Plug.Conn.read_body(conn)
      send(test, {:invoke_model, Jason.decode!(body)["model"]})

      send(
        test,
        {:invoke_auth, Plug.Conn.get_req_header(conn, "authorization"),
         Plug.Conn.get_req_header(conn, "x-api-key")}
      )

      Plug.Conn.resp(conn, 400, ~s({"message":"stop here"}))
    end)

    client =
      BedrockAgentCore.Client.new(
        credentials: %{
          access_key_id: "AKID",
          secret_access_key: "secret",
          region: "us-east-1",
          security_token: nil
        },
        base_url: "http://localhost:#{bypass.port}"
      )

    assert {:error, _} =
             Session.run(BedrockAgentCore,
               handler: fn _, _, _ -> {:ok, ""} end,
               prompt: "hi",
               harness_arn: "arn:new",
               runtime_session_id: String.duplicate("s", 33),
               client: client,
               invoke_retries: 0,
               model_config: model_config("agentcore_control_plane", bypass),
               timeout: 5_000
             )

    assert_received {:invoke_auth, ["AWS4-HMAC-SHA256 " <> _signature], []}
    refute Map.has_key?(model_config("agentcore_control_plane", bypass), :api_key)
    refute Map.has_key?(model_config("agentcore_control_plane", bypass), :base_url)

    assert_received {:invoke_model,
                     %{"bedrockModelConfig" => %{"modelId" => "us.anthropic.claude-sonnet-4-6"}}}
  end

  test "CMA refuses Local's runtime model before creating a session" do
    bypass = Bypass.open()
    test = self()

    Bypass.stub(bypass, "POST", "/v1/v1/sessions", fn conn ->
      send(test, :unexpected_cma_request)
      Plug.Conn.resp(conn, 400, "")
    end)

    assert {:error, :runtime_model_unsupported} =
             Session.run(ClaudeManagedAgents,
               handler: fn _, _, _ -> {:ok, ""} end,
               prompt: "hi",
               agent_id: "agent",
               environment_id: "env",
               model_config: model_config("local_data_plane", bypass)
             )

    refute_received :unexpected_cma_request
  end

  test "AgentCore refuses Local's data plane before invoking" do
    bypass = Bypass.open()

    assert {:error, :data_plane_unsupported} =
             Session.run(BedrockAgentCore,
               handler: fn _, _, _ -> {:ok, ""} end,
               prompt: "hi",
               harness_arn: "arn:new",
               runtime_session_id: String.duplicate("s", 33),
               invoke_fun: fn _ -> flunk("AgentCore must refuse before invoking") end,
               model_config: Map.delete(model_config("local_data_plane", bypass), :model)
             )
  end
end
